// Builds the draft-07 JSON Schema bundle: every component under `definitions`. Draft-07 because
// typify reads schemas through schemars' draft-07 model; ADR 0003.
import { toJsonSchemas } from './components.js';

export function buildJsonSchemaBundle() {
  return {
    $schema: 'http://json-schema.org/draft-07/schema#',
    title: 'Pulse contract',
    $comment:
      '@generated by `pnpm --filter @pulse/contract generate` from packages/contract/src; do not edit.',
    definitions: toJsonSchemas('draft-07', '#/definitions/'),
  };
}
